  function resetRotation(id){
    const monitor=state.monitors.find(m=>m.id===id);if(!monitor)return;
    openModal('核查后恢复自动换 IP',`<p class="confirmation-text">恢复 <strong>${e(monitor.name)}</strong> 的自动操作，并清零连续失败计数。</p><div class="notice warning">${icon('warning')}<div>请先在 AWS 控制台核实实例当前公网 IP、新 EIP 是否已关联及旧 EIP 是否仍占用。上次操作超时或失败时，实际云端状态可能已发生变化。</div></div><p class="form-description section-space">此操作不会立即更换 IP。恢复后，任务按原计划检测并重新累计失败；达到连续失败轮数后可再次触发更换。</p><label class="check-field"><input type="checkbox" required><span>我已核实 AWS 中的实际资源状态，确认恢复此任务。</span></label>`,{submit:'恢复自动换 IP',onSubmit:async()=>{await post(`/monitors/${encodeURIComponent(id)}/reset-rotation`);await finishMutation('自动操作暂停已解除，等待下次计划检测。');}});
  }
  function addProbe(){openModal('接入远程探针',`<p class="form-description">先在对应网络位置部署项目附带的探针服务，再填写它的 HTTPS 接口地址与 Token。</p><div class="form-grid">${field('probe-name','探针名称','<input id="probe-name" name="name" maxlength="80" placeholder="例如：上海探针" required>')}${field('probe-region','实际网络位置','<select id="probe-region" name="region_type"><option value="mainland">中国大陆</option><option value="overseas">境外</option></select>')}${field('probe-url','HTTPS 探针接口','<input id="probe-url" name="url" type="url" placeholder="https://probe.example.com/probe" pattern="https://.+" required>','填写完整 /probe 地址，必须是公网 HTTPS，禁止重定向。',true)}${field('probe-token','Probe Token','<input id="probe-token" name="token" type="password" minlength="24" maxlength="512" autocomplete="new-password" placeholder="至少 24 位，与探针服务配置一致" required>','Token 会加密保存，后续读取不返回明文。',true)}</div><div class="notice section-space">${icon('globe')}<div>接入国内、境外两个探针后可对比网络路径。仅某一侧不可达会标记为“疑似路径受限”，不能作为确定的封锁判断。</div></div>`,{submit:'保存探针',onSubmit:async(data,form)=>{await post('/probes',{name:trim(data.get('name')),region_type:String(data.get('region_type')),url:trim(data.get('url')),token:trim(data.get('token'))});form.reset();await finishMutation('探针已配置，下次检测时会尝试连接。');}});}
  function confirmDelete(kind,id){const config={account:{items:state.accounts,path:'accounts',title:'移除 AWS 账号',description:'仅移除本面板保存的凭证，不会删除 AWS 中的实例、弹性 IP 或其他资源。若账号有关联检测任务，请先删除那些任务。'},script:{items:state.scripts,path:'scripts',title:'删除开机脚本',description:'删除脚本库中的这份模板。已提交到 EC2 的 User Data 不受影响。'},monitor:{items:state.monitors,path:'monitors',title:'删除检测任务',description:'停止该任务后续的定时检测，并删除本地任务记录。不会修改 EC2 实例。'},probe:{items:state.probes,path:'probes',title:'移除远程探针',description:'从后续检测中移除此探针。本机 TCP 检测会继续运行。'}}[kind];const item=config.items.find(v=>v.id===id);if(!item)return;openModal(config.title,`<p class="confirmation-text">确认${config.title} <strong>${e(item.name)}</strong>？</p><p class="form-description">${config.description}</p>`,{submit:`确认${config.title}`,onSubmit:async()=>{await remove(`/${config.path}/${encodeURIComponent(id)}`);await finishMutation('已完成。');}});}
  function showResult(id){const r=state.results.find(item=>item.id===id);if(!r)return;const rotation=r.rotation;openModal('TCP 检测与自动换 IP 详情',`<div class="details-grid"><div><small>检测任务</small>${e(r.monitor_name||r.instance_id)}</div><div><small>TCP 状态</small>${badge(r.status)}</div><div><small>目标</small><span class="mono">${e(r.target_ip||'无公网 IP')}:${e(r.port)}</span></div><div><small>检测时间</small>${e(shortDate(r.checked_at))}</div><div><small>连接成功 / 采样</small>${e(r.success_count??0)} / ${e(r.samples??'—')}</div><div><small>平均 TCP 耗时</small>${r.latency_ms==null?'—':e(r.latency_ms)+' ms'}</div><div><small>未连接比例</small>${r.loss_percent==null?'—':e(r.loss_percent)+'%'}</div><div><small>GFW 线索</small>${badge(r.gfw_status||'insufficient_evidence')}</div></div><p class="result-summary">${e(r.summary||'单点 TCP 结果只能反映当前路径连通性，不能直接判断 GFW 封锁。')}</p>${rotation?`<section class="rotation-detail"><div class="rotation-detail-heading"><strong>${icon('ip')}自动换 IP</strong>${rotationBadge(rotation.status)}</div><p class="result-summary">${e(rotation.message||'本次自动操作结果已记录。')}</p>${rotation.old_ip||rotation.new_ip?`<div class="details-grid"><div><small>原 IP</small><span class="mono">${e(rotation.old_ip||'—')}</span></div><div><small>新 IP</small><span class="mono">${e(rotation.new_ip||'—')}</span></div></div>`:''}${rotation.verification?`<div class="verification-summary"><span>更换后 TCP 复测</span>${badge(rotation.verification.status||'unknown')}<p>${e(rotation.verification.summary||'复测结果仅反映当时端口连通性。')}</p></div>`:''}</section>`:`<div class="notice section-space">${icon('info')}<div>此记录只有检测结果，未执行自动换 IP。</div></div>`}<label class="section-space">详细观测</label><pre class="observations">${e(asArray(r.observations).length?JSON.stringify(r.observations,null,2):'暂无额外探针观测。')}</pre>`,{wide:true,eyebrow:'TCP INSPECTION'});}
  async function runMonitor(id,buttonEl){if(readOnly())return;buttonEl.disabled=true;buttonEl.classList.add('rotating');toast('正在进行 TCP 握手检测，本次不会自动更换 IP。','info');try{const result=await post(`/monitors/${encodeURIComponent(id)}/run`);await refreshData(false,false);toast(result.result?.summary||'检测已完成。',result.result?.status==='reachable'?'success':'info');}catch(err){toast(err.message,'error');}finally{buttonEl.disabled=false;buttonEl.classList.remove('rotating');}}
